            "log_detail_patterns": [
                // Not yet localized: explicit English fallback, identical to
                // the backend text (main.js previously relied on implicit fallback).
                [/^Real-time file protection is on \(watching the user profile for file changes\)$/, "Real-time file protection is on (watching the user profile for file changes)"],
                [/^Real-time file protection cannot monitor (.+); will retry$/, "Real-time file protection cannot monitor {1}; will retry"],
                [/^No file activity for (\d+)s; rescanning to make sure nothing was missed$/, "No file activity for {1}s; rescanning to make sure nothing was missed"],
                [/^Too many files changing at once; running a full rescan$/, "Too many files changing at once; running a full rescan"],
                [/^File events were dropped during heavy activity; running a full rescan$/, "File events were dropped during heavy activity; running a full rescan"],
                [/^File monitoring hit an error; running a full rescan$/, "File monitoring hit an error; running a full rescan"],
                [/^Real-time file protection cannot watch (.+); will retry$/, "Real-time file protection cannot watch {1}; will retry"],
                [/^File monitoring stopped responding; running a full rescan$/, "File monitoring stopped responding; running a full rescan"],
                [/^model=(.+?) skipped: decided within (\d+(?:\.\d+)?)s delay window$/, "النموذج {1}: تم تخطي التحليل، اتخذ المستخدم القرار خلال نافذة الانتظار مدتها {2} ثانية"],
                [/^model=(.+?) cancelled after (\d+(?:\.\d+)?)s \(user decided\)$/, "النموذج {1}: أُلغي بعد {2} ثانية (قرر المستخدم بنفسه)"],
                [/^model=(.+?) state=failed from_cache=(?:True|False) elapsed=(\d+(?:\.\d+)?)s$/, "فشل تحليل النموذج {1} ({2} ثانية)"],
                [/^model=(.+?) verdict=allow from_cache=(?:True|False) elapsed=(\d+(?:\.\d+)?)s reason=(.*)$/, "اقتراح النموذج {1}: السماح ({2} ثانية): {3}"],
                [/^model=(.+?) verdict=block from_cache=(?:True|False) elapsed=(\d+(?:\.\d+)?)s reason=(.*)$/, "اقتراح النموذج {1}: الحجب ({2} ثانية): {3}"],
                [/^(.+) \/ block$/, "تم الحجب وفق اقتراح الذكاء الاصطناعي: {1}"],
                [/^(.+) \/ allow$/, "تم السماح وفق اقتراح الذكاء الاصطناعي: {1}"],
            ],
